1	@import "tailwindcss";
2	
3	/* =====================================================================
4	   HEARD — Design tokens (ported from the design system colors_and_type.css)
5	   Warm, trustworthy, accessible-first. Body floor 18px. AA floor, AAA body.
6	   Fonts (Lora display + Nunito Sans body) are loaded via next/font in
7	   app/layout.tsx and exposed as --font-lora / --font-nunito-sans.
8	   ===================================================================== */
9	
10	@theme {
11	  /* ---- Color: brand palette (exact tokens from brief) ------------- */
12	  --color-bg: #fbf7f2; /* warm off-white page background */
13	  --color-surface: #ffffff; /* cards, sheets */
14	  --color-surface-sunk: #f4eee5; /* recessed wells, track backgrounds */
15	
16	  --color-ink: #2a2622; /* primary text (warm near-black) */
17	  --color-ink-soft: #6b6259; /* secondary text */
18	  --color-ink-faint: #948b81; /* tertiary / placeholder */
19	
20	  --color-primary: #136f63; /* calm teal — trust; primary buttons */
21	  --color-primary-dark: #0e5249; /* hover / active */
22	  --color-primary-tint: #e4efec; /* teal wash — selected chips, fills */
23	
24	  --color-accent: #e08a3c; /* warm amber — tips, gentle highlights */
25	  --color-accent-dark: #c4732c; /* amber hover / active */
26	  --color-accent-tint: #fbebd9; /* amber wash */
27	
28	  --color-success: #2e7d5b; /* available / positive (pair w/ text) */
29	  --color-success-tint: #e3f0ea;
30	  --color-alert: #b23a2e; /* errors / safety (pair w/ text) */
31	  --color-alert-tint: #f7e6e3;
32	
33	  --color-border: #ece3d8; /* hairlines, dividers */
34	  --color-border-strong: #d9ccbc; /* input borders, stronger separation */
35	  --color-focus: #1b6fb0; /* high-visibility focus ring (3px) */
36	
37	  /* ---- Type families --------------------------------------------- */
38	  --font-display: var(--font-lora), Georgia, "Times New Roman", serif;
39	  --font-body: var(--font-nunito-sans), system-ui, -apple-system, sans-serif;
40	
41	  /* ---- Type scale (rem from 16px root). Body floor = 18px -------- */
42	  --text-xs: 0.875rem; /* 14px — meta / fine print */
43	  --text-sm: 1rem; /* 16px — labels, secondary */
44	  --text-base: 1.125rem; /* 18px — BODY MINIMUM */
45	  --text-lg: 1.25rem; /* 20px — large body / lead */
46	  --text-h3: 1.5rem; /* 24px */
47	  --text-h2: 1.875rem; /* 30px */
48	  --text-h1: 2.375rem; /* 38px */
49	  --text-display: 2.875rem; /* 46px */
50	
51	  --leading-tight: 1.2;
52	  --leading-snug: 1.35;
53	  --leading-body: 1.6;
54	
55	  /* ---- Radii ----------------------------------------------------- */
56	  --radius-sm: 8px;
57	  --radius-btn: 12px;
58	  --radius-card: 16px;
59	  --radius-lg: 24px;
60	  --radius-pill: 999px;
61	
62	  /* ---- Shadows — soft, low, warm --------------------------------- */
63	  --shadow-xs: 0 1px 2px rgba(42, 38, 34, 0.05);
64	  --shadow-sm: 0 2px 8px rgba(42, 38, 34, 0.06);
65	  --shadow-md: 0 6px 20px rgba(42, 38, 34, 0.08);
66	  --shadow-lg: 0 14px 40px rgba(42, 38, 34, 0.12);
67	
68	  /* ---- Layout ----------------------------------------------------- */
69	  /* Desktop-first. The main section spans 85% of the viewport, capped so text
70	     lines stay readable for the low-vision audience on very large monitors.
71	     Exposed as the `app` container size → utilities `max-w-app` / `w-app`. */
72	  --container-app: 1500px;
73	
74	  /* ---- Min interactive target ------------------------------------ */
75	  --tap-min: 48px;
76	
77	  /* ---- Motion (gentle; respect reduced-motion) ------------------- */
78	  --ease-warm: cubic-bezier(0.33, 0.1, 0.25, 1);
79	}
80	
81	/* =====================================================================
82	   SEMANTIC ELEMENT DEFAULTS
83	   In @layer base so Tailwind utilities (e.g. text-surface on a heading over
84	   the teal panel) can override these element defaults — unlayered rules would
85	   otherwise win over layered utilities in the cascade.
86	   ===================================================================== */
87	
88	@layer base {
89	  html {
90	    font-size: 16px;
91	  }
92	
93	  body {
94	    background: var(--color-bg);
95	    color: var(--color-ink);
96	    font-family: var(--font-body);
97	    font-size: var(--text-base);
98	    line-height: var(--leading-body);
99	    font-weight: 400;
100	    -webkit-font-smoothing: antialiased;
101	    text-rendering: optimizeLegibility;
102	  }
103	
104	  h1,
105	  h2,
106	  h3,
107	  h4 {
108	    font-family: var(--font-display);
109	    /* Inherit color (ink by default) so a coloured parent — e.g. the teal auth
110	       panel with text-surface — recolours headings without a specificity fight. */
111	    color: inherit;
112	    line-height: var(--leading-tight);
113	    text-wrap: balance;
114	    margin: 0;
115	  }
116	  h1 {
117	    font-size: var(--text-h1);
118	    font-weight: 700;
119	    letter-spacing: -0.01em;
120	  }
121	  h2 {
122	    font-size: var(--text-h2);
123	    font-weight: 700;
124	    letter-spacing: -0.01em;
125	  }
126	  h3 {
127	    font-size: var(--text-h3);
128	    font-weight: 700;
129	  }
130	
131	  p {
132	    margin: 0;
133	    text-wrap: pretty;
134	  }
135	
136	  a {
137	    color: var(--color-primary);
138	    text-underline-offset: 3px;
139	  }
140	  a:hover {
141	    color: var(--color-primary-dark);
142	  }
143	}
144	
145	/* ---- Universal visible focus — the single most important rule ----- */
146	:where(
147	    a,
148	    button,
149	    input,
150	    select,
151	    textarea,
152	    [tabindex],
153	    [role="button"],
154	    [role="tab"],
155	    [role="switch"]
156	  ):focus-visible {
157	  outline: none;
158	  box-shadow: 0 0 0 3px var(--color-focus);
159	  border-radius: var(--radius-sm);
160	}
161	
162	/* Gentle waveform used by the voice player; static under reduced motion. */
163	@keyframes wf {
164	  from {
165	    transform: scaleY(0.4);
166	  }
167	  to {
168	    transform: scaleY(1);
169	  }
170	}
171	
172	@media (prefers-reduced-motion: reduce) {
173	  *,
174	  *::before,
175	  *::after {
176	    animation-duration: 0.001ms !important;
177	    animation-iteration-count: 1 !important;
178	    transition-duration: 0.001ms !important;
179	  }
180	}
