// Calculate WCAG contrast ratio between #e4efec (bg) and #6b6259 (text)

function hex2rgb(hex) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : null;
}

function getLuminance(rgb) {
  const [r, g, b] = [rgb.r, rgb.g, rgb.b].map(val => {
    val = val / 255;
    return val <= 0.03928 ? val / 12.92 : Math.pow((val + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function getContrastRatio(color1, color2) {
  const lum1 = getLuminance(color1);
  const lum2 = getLuminance(color2);
  const lighter = Math.max(lum1, lum2);
  const darker = Math.min(lum1, lum2);
  return (lighter + 0.05) / (darker + 0.05);
}

const bg = hex2rgb('#e4efec');
const text = hex2rgb('#6b6259');

console.log('Background (#e4efec):', bg);
console.log('Text (#6b6259):', text);
console.log('');

const ratio = getContrastRatio(bg, text);
console.log('Contrast ratio:', ratio.toFixed(2) + ':1');
console.log('');
console.log('WCAG AA requirement for body text (18px+): 4.5:1');
console.log('WCAG AAA requirement for body text: 7:1');
console.log('');
console.log('Pass WCAG AA?', ratio >= 4.5 ? 'YES' : 'NO ❌');
console.log('Pass WCAG AAA?', ratio >= 7 ? 'YES' : 'NO');
